export const SUPPORTING_METRICS: MetricDefinition[] = SUPPORTING.map(([key, name, module, unit, betterWhen, description, dataSource, eventDate]) => ({
  key, name, description, formula: description, dataSource, eventDate: eventDate ?? "in period", inclusion: "All records of the facility (or of the signed-in user)", exclusion: "Cancelled and draft records unless stated",
  module, unit, betterWhen, targetable: false, lastUpdated: U,
}));

const BY_KEY = new Map([...METRICS, ...SUPPORTING_METRICS].map((m) => [m.key, m]));

export function getMetric(key: string): MetricDefinition | undefined {
  return BY_KEY.get(key);
}

export function requireMetric(key: string): MetricDefinition {
  const m = BY_KEY.get(key);
  if (!m) throw new Error(`Unregistered analytics metric "${key}"`);
  return m;
}

export function metricsForModule(module: MetricModule): MetricDefinition[] {
  return METRICS.filter((m) => m.module === module);
}

export const TARGETABLE_METRICS = METRICS.filter((m) => m.targetable);
